UPDATE ai_agent_step_run
SET status         = #{status},
    output_summary = #{outputSummary},
    error_message  = #{errorMessage},
    cost_millis    = #{costMillis},
    end_time       = #{endTime},
    update_time    = #{updateTime}
WHERE run_id = #{runId}
  AND step_id = #{stepId}
